input.command:
which bd >/dev/null 2>&1 && {
bd create "Audio capture loses ~10% of every second (avfoundation drops samples)" --description="ffmpeg 8.1.1 avfoundation indev delivers ~90% of real-time samples. Measured: -t 20 run took 21.11s wall clock, ffmpeg reported timeline 20.00s, file held only 18.04s of PCM. Live data: 68 one-second chunks over a 70s recording = 60.39s of audio. Every chunk_NNN.wav is 0.885-0.917s instead of 1.000s, so loss is spread evenly (~100ms per second), not one gap. Ruled out: segment muxer (continuous file loses the same), resampling (native 48k loses the same), -thread_queue_size, -use_wallclock_as_timestamps, -drop_late_frames false, -capture_raw_data, device :default vs :0 vs -audio_device_index. Root cause is inside ffmpeg's avfoundation input device. This is the primary cause of dropped words AND of whisper 'beautifying' text (it reconstructs the missing audio). Next: test ffmpeg@7/@6 from brew, or replace capture with a native AVAudioEngine helper." -t bug -p 0 --json 2>&1 | tail -3
bd create "55s segment boundary loses/duplicates words and re-detects language per segment" --description="FINAL_SEGMENT_SECS=55 (init.lua:1147) hard-cuts audio with no overlap and no carried context. Observed in log 03:25:51: seg1 ended '...чтобы меня передавали.' and seg2 began 'давали по звучанию.' — the word straddling the cut was mangled. Each segment also runs its own independent -l auto detection, so one dictation can be split across two languages. Only affects recordings >55s." -t bug -p 1 --json 2>&1 | tail -3
bd create "Mixed-language speech: -l auto normalizes toward one language, no verbatim prompt" --description="User speaks a Ukrainian/Russian/English mix and wants phonetic/verbatim output. Currently -l auto picks ONE language per segment (always detected 'ru' in samples) and whisper normalizes toward it, rewriting Ukrainian and English words. ~/.local-whisper/prompt does not exist so getPromptArgs() returns {} — no vocabulary or style anchoring. No decoding params set (temperature, beam size, entropy-thold all default), so temperature fallback pushes toward invention on damaged audio." -t feature -p 1 --json 2>&1 | tail -3
bd create "Recording ffmpeg stderr is discarded, hiding capture faults" --description="init.lua:1373-1377 termination callback ignores the err argument and no streaming callback is attached, so ffmpeg's warnings during recording are never logged. The ~10% sample loss was invisible for an unknown period. Log the sample count vs wall clock per recording as a health check." -t task -p 2 --json 2>&1 | tail -3
} || echo "bd NOT on PATH"
